scenario.irule:
when FLOW_INIT {
  ACL::action drop
}
when CLIENT_ACCEPTED {
  if {[ACL::eval -l7] != 1} { error acl-evaluation-mismatch }
}

when HTTP_REQUEST {
  set generated [AES::key 128]
  set static_key {AES 128 00112233445566778899aabbccddeeff}
  set ciphertext [AES::encrypt $static_key hello]
  set plaintext [AES::decrypt $static_key $ciphertext]
  if {[lindex $generated 1] ne "128" || $plaintext ne "hello"} { error aes-round-trip-mismatch }
}

when HTTP_REQUEST {
  set ::state::connection::client_payload [binary format H* 30080201020403686579]
  set root [ASN1::element init BER]
  set child [ASN1::element next $root]
  set decoded [ASN1::decode $root "(ia)" number value]
  set encoded [ASN1::encode DER "?ia" "" payload]
  set optional [ASN1::decode $encoded "?ia" missing payload_value]
  ASN1::encode replace $root 2 i 3
  if {$decoded != 2 || $number != 2 || $value ne "hey" || $optional != 1 || [info exists missing] || $payload_value ne "payload" || [ASN1::element tag $child] != 2} { error asn1-round-trip-mismatch }
}
